def create_default_roles(apps, schema_editor):
    Tenant = apps.get_model('tenants', 'Tenant')
    CompanyRole = apps.get_model('staff', 'CompanyRole')
    Employee = apps.get_model('staff', 'Employee')
    all_permissions = [
        'appointments_view', 'appointments_manage', 'clients_view', 'clients_manage',
        'services_view', 'services_manage', 'inventory_view', 'inventory_manage',
        'inventory_count', 'analytics_view', 'expenses_manage', 'staff_view',
        'staff_manage', 'settings_manage',
    ]
    worker_permissions = [
        'appointments_view', 'clients_view', 'services_view',
        'inventory_view', 'inventory_count', 'staff_view',
    ]
    for tenant in Tenant.objects.all():
        admin = CompanyRole.objects.create(tenant=tenant, name='Администратор', builtin_key='admin', permissions=all_permissions)
        polisher = CompanyRole.objects.create(tenant=tenant, name='Полировщик', builtin_key='polisher', permissions=worker_permissions)
        detailer = CompanyRole.objects.create(tenant=tenant, name='Детейлер', builtin_key='detailer', permissions=worker_permissions)
        for employee in Employee.objects.filter(tenant=tenant):
            position = (employee.position or '').lower()
            role = admin if 'админ' in position else (polisher if 'полир' in position else detailer)
            employee.company_role = role
            employee.save(update_fields=['company_role'])


def remove_default_roles(apps, schema_editor):
    apps.get_model('staff', 'CompanyRole').objects.filter(builtin_key__in=['admin', 'polisher', 'detailer']).delete()


